import uuid,os,re
existing=set()
for f in os.listdir('alembic/versions'):
    if f.endswith('.py'):
        m=re.search(r'^revision(?::\s*str)?\s*=\s*[\"\'](.+?)[\"\']',open('alembic/versions/'+f).read(),re.M)
        if m: existing.add(m.group(1))
while True:
    r=uuid.uuid4().hex[:12]
    if r not in existing and not r.isdigit(): print(r); break
